INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'JDBC a databáze — připojení, prepared statements', '<h2>JDBC</h2><p>Java Database Connectivity — standardní API pro přístup k relačním databázím. <code>DriverManager</code> vytvoří spojení, <code>PreparedStatement</code> pro bezpečné dotazy.</p><pre><code>import java.sql.*;\n\nString url = "jdbc:mysql://localhost:3306/appdb";\n\ntry (Connection conn = DriverManager.getConnection(url, "user", "pass")) {\n    // Vytvoreni tabulky\n    try (Statement stmt = conn.createStatement()) {\n        stmt.execute("CREATE TABLE IF NOT EXISTS users "\n            + "(id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100))");\n    }\n\n    // Bezpecny insert s PreparedStatement\n    try (PreparedStatement ps = conn.prepareStatement(\n            "INSERT INTO users (name) VALUES (?)")) {\n        ps.setString(1, "Karel");\n        ps.executeUpdate();\n    }\n\n    // Cteni\n    try (PreparedStatement ps = conn.prepareStatement(\n            "SELECT * FROM users WHERE id = ?")) {\n        ps.setInt(1, 1);\n        ResultSet rs = ps.executeQuery();\n        if (rs.next()) {\n            System.out.println(rs.getString("name"));\n        }\n    }\n}</code></pre><p>Vždy používej <code>PreparedStatement</code> — chrání před SQL injekcí. Vždy zavírej <code>Connection</code> pomocí try-with-resources.</p>', 'lesson', 18, 15, 16),

(@kurs_id, 'Spring Boot intro — REST API, @RestController, DI', '<h2>Spring Boot</h2><p>Rámec pro rychlou tvorbu Java aplikací. Automatická konfigurace, vestavěný server, minimalizace boilerplate. Start na <a href="https://start.spring.io">start.spring.io</a>.</p><pre><code>@SpringBootApplication\npublic class App {\n    public static void main(String[] args) {\n        SpringApplication.run(App.class, args);\n    }\n}</code></pre><h2>REST Controller</h2><pre><code>@RestController\n@RequestMapping("/api/users")\npublic class UserController {\n\n    private final UserService userService;\n\n    // Dependency Injection pres konstruktor\n    public UserController(UserService userService) {\n        this.userService = userService;\n    }\n\n    @GetMapping\n    public List&lt;User&gt; all() {\n        return userService.findAll();\n    }\n\n    @GetMapping("/{id}")\n    public User one(@PathVariable Long id) {\n        return userService.findById(id);\n    }\n\n    @PostMapping\n    @ResponseStatus(HttpStatus.CREATED)\n    public User create(@RequestBody User user) {\n        return userService.save(user);\n    }\n\n    @DeleteMapping("/{id}")\n    public void delete(@PathVariable Long id) {\n        userService.deleteById(id);\n    }\n}</code></pre><h2>Dependency Injection</h2><p><code>@Service</code>, <code>@Repository</code>, <code>@Component</code> — Spring automaticky spravuje instance (beany). Injektuje přes konstruktor — doporučený způsob.</p><pre><code>@Service\npublic class UserService {\n    private final UserRepository repo;\n    public UserService(UserRepository repo) { this.repo = repo; }\n    public List&lt;User&gt; findAll() { return repo.findAll(); }\n}</code></pre>', 'lesson', 19, 15, 18),

(@kurs_id, 'Testování — JUnit 5, Mockito, parametrické testy', '<h2>JUnit 5</h2><p>Standardní testovací rámec pro Javu. Anotace: <code>@Test</code>, <code>@BeforeEach</code>, <code>@DisplayName</code>. Asserce: <code>assertEquals</code>, <code>assertTrue</code>, <code>assertThrows</code>.</p><pre><code>import org.junit.jupiter.api.*;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass KalkulackaTest {\n    private Kalkulacka k;\n\n    @BeforeEach\n    void setUp() { k = new Kalkulacka(); }\n\n    @Test\n    @DisplayName("Soucet dvou cisel")\n    void soucet() {\n        assertEquals(5, k.soucet(2, 3));\n    }\n\n    @Test\n    void deleniNulou() {\n        assertThrows(ArithmeticException.class,\n            () -> k.deleni(10, 0));\n    }\n}</code></pre><h2>Mockito</h2><p>Mockování závislostí — izoluje testovanou třídu od externích služeb.</p><pre><code>@ExtendWith(MockitoExtension.class)\nclass UserServiceTest {\n    @Mock UserRepository repo;\n    @InjectMocks UserService service;\n\n    @Test\n    void findById() {\n        when(repo.findById(1L))\n            .thenReturn(Optional.of(new User("Karel")));\n        User u = service.findById(1L);\n        assertEquals("Karel", u.getJmeno());\n        verify(repo).findById(1L);\n    }\n}</code></pre><h2>Parametrické testy</h2><pre><code>@ParameterizedTest\n@CsvSource({"1,1,2", "2,3,5", "10,-5,5"})\nvoid soucet(int a, int b, int expected) {\n    assertEquals(expected, new Kalkulacka().soucet(a, b));\n}</code></pre>', 'lesson', 20, 15, 16);


