INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Co je JVM?', 'Java Virtual Machine — spouští bytecode na jakékoliv platformě', 'Java Visual Manager', 'Java Variable Module', 'Java Version Manager', 'a', 'JVM (Java Virtual Machine) je virtuální stroj, který spouští Java bytecode nezávisle na platformě.', 1),
(@qfin, 'Jaký je rozdíl mezi == a .equals() u řetězců?', 'Žádný rozdíl', '== porovnává reference, .equals() obsah', '.equals() je rychlejší', '== porovnává obsah, .equals() referenci', 'b', '== porovnává reference (identitu objektu), .equals() porovnává logickou rovnost obsahu řetězce.', 2),
(@qfin, 'Co dělá switch expression v Javě 14+?', 'Je to stará syntaxe switch', 'Vrací hodnotu a používá -> místo case:', 'Nemůže mít default', 'Vždy vyžaduje break', 'b', 'Switch expression vrací hodnotu, používá šipkovou syntaxi -> a nepotřebuje break.', 3),
(@qfin, 'Co je varargs v Javě?', 'Proměnná deklarovaná klíčovým slovem var', 'Metoda přijímající proměnlivý počet argumentů jako pole', 'Dynamický typ', 'Výchozí hodnota parametru', 'b', 'Varargs (Typ... nazev) umožňuje metodě přijmout libovolný počet argumentů stejného typu jako pole.', 4),
(@qfin, 'Jaký je rozdíl mezi ArrayList a LinkedList?', 'ArrayList je synchronizovaný', 'ArrayList má rychlý náhodný přístup, LinkedList rychlé vkládání/mazání', 'LinkedList neumožňuje null', 'Žádný rozdíl', 'b', 'ArrayList je založen na poli (rychlý get/set), LinkedList na spojovém seznamu (rychlé add/remove na koncích).', 5),
(@qfin, 'Co dělá Optional.ofNullable(x)?', 'Vytvoří Optional, které je vždy prázdné', 'Vytvoří Optional z x, nebo empty pokud x je null', 'Vyvolá výjimku pokud x je null', 'Převede Optional na stream', 'b', 'Optional.ofNullable() vytvoří Optional s hodnotou x, nebo prázdné Optional pokud x je null.', 6),
(@qfin, 'Co je sealed class v Javě 17+?', 'Třída, kterou nelze instanciovat', 'Třída s omezenou dědičností — uvádí povolené podtřídy', 'Třída bez metod', 'Třída s privátním konstruktorem', 'b', 'Sealed class omezuje, které třídy mohou dědit — pomocí permits uvádí povolené podtřídy.', 7),
(@qfin, 'Co dělá try-with-resources?', 'Zachytí všechny výjimky', 'Automaticky zavře resource implementující AutoCloseable', 'Vytvoří nové vlákno', 'Otevře soubor pro čtení', 'b', 'try-with-resources automaticky zavře všechny resource implementující AutoCloseable na konci bloku.', 8),
(@qfin, 'Co je CompletableFuture v Javě?', 'Futures, které nelze zrušit', 'Asynchronní výpočet s možností řetězení operací', 'Synchronní HTTP klient', 'Druh kolekce', 'b', 'CompletableFuture umožňuje asynchronní výpočet s řetězením operací thenApply, thenAccept, thenCompose.', 9),
(@qfin, 'K čemu slouží @RestController v Spring Boot?', 'Definuje HTML šablonu', 'Označuje třídu, která obsluhuje HTTP požadavky a vrací JSON/data', 'Vytvoří databázovou tabulku', 'Spustí aplikaci', 'b', '@RestController kombinuje @Controller a @ResponseBody — metody vrací data (JSON) místo názvů šablon.', 10);


